<script setup lang="ts">
import {computed,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {api,money,type UserProfileView,type PublicReview,type Product,type PageResult} from '../api/client';
import {useWorkLoad} from '../lib/workLoad';
import {useSession} from '../stores/session';
import {homeFor,returnTo} from '../lib/access';
import {pageNumber,profileQuery} from '../lib/userProfiles';
import PageState from '../components/PageState.vue';
import CreditCard from '../components/CreditCard.vue';
import PublicReviews from '../components/PublicReviews.vue';
import ProductPhoto from '../components/ProductPhoto.vue';
import StatusBadge from '../components/StatusBadge.vue';
import WorkPagination from '../components/WorkPagination.vue';
const route=useRoute(),router=useRouter(),session=useSession(),id=String(route.params.id);
const base='/users/'+encodeURIComponent(id),context=profileQuery(route.query);
const productStatus=computed(()=>['AVAILABLE','SOLD'].includes(String(route.query.status))?String(route.query.status):'ALL');
const reviewRole=computed(()=>['BUYER','SELLER'].includes(String(route.query.role))?String(route.query.role):'ALL');
const tab=computed(()=>route.query.tab==='reviews'?'reviews':'products');
const back=computed(()=>returnTo(route.query.from,session.user?.role,id===session.user?.id?'/profile':homeFor(session.user?.role),['/products','/orders','/cases','/moderation','/reports','/profile','/admin','/support']));
const {data,loading,error,reload}=useWorkLoad(()=>api<UserProfileView>(base+'/profile?'+context));
const products=useWorkLoad(()=>api<PageResult<Product>>(base+'/products?'+new URLSearchParams([...context,['status',productStatus.value],['page',String(pageNumber(route.query.productPage))]])),false,()=>productStatus.value+':'+pageNumber(route.query.productPage));
const reviews=useWorkLoad(()=>api<PageResult<PublicReview>>(base+'/reviews?'+new URLSearchParams([...context,['role',reviewRole.value],['page',String(pageNumber(route.query.reviewPage))]])),false,()=>reviewRole.value+':'+pageNumber(route.query.reviewPage));
watch([productStatus,()=>route.query.productPage],()=>void products.reload());
watch([reviewRole,()=>route.query.reviewPage],()=>void reviews.reload());
function change(values:Record<string,string>){void router.replace({query:{...route.query,...values}})}
function refresh(){void reload();void products.reload();void reviews.reload()}
const gender=(value:string)=>(({MALE:'男',FEMALE:'女',OTHER:'其他'} as Record<string,string>)[value]||'未填写');
</script>
<template><RouterLink class="back-link" :to="back">← 返回原页面</RouterLink><PageState :loading="loading" :error="error" @retry="reload"><div v-if="data" class="stack"><header class="panel stack profile-header"><div class="row spread"><div class="profile-identity"><img v-if="data.avatarUrl" class="profile-avatar" :src="data.avatarUrl" :alt="data.displayName+'的头像'"/><span v-else class="profile-avatar avatar-placeholder" aria-label="默认头像">{{data.displayName.slice(0,1)}}</span><div><p class="eyebrow">用户资料</p><h1>{{data.displayName}}</h1><p class="muted work-id">用户编号 {{data.id}}</p></div></div><button class="button" @click="refresh">刷新资料</button></div><dl class="facts"><dt>学校</dt><dd>{{data.school||'未填写'}}</dd><dt>校区</dt><dd>{{data.campus||'未填写'}}</dd><dt>性别</dt><dd>{{gender(data.gender)}}</dd><dt>个人简介</dt><dd class="preserve">{{data.bio||'未填写'}}</dd></dl></header><div class="credit-grid"><CreditCard title="买家信用" :credit="data.buyerCredit"/><CreditCard title="卖家信用" :credit="data.sellerCredit"/></div><section v-if="data.context&&session.user?.role!=='USER'" class="panel stack" aria-label="关联工作记录"><h2>{{data.context.title}}</h2><dl class="facts"><template v-for="(detail,index) in data.context.details" :key="index"><dt>{{detail.label}}</dt><dd class="preserve">{{detail.value}}</dd></template></dl><div class="row"><RouterLink v-for="link in data.context.links" :key="link.path" class="button" :to="{path:link.path.split('?')[0],query:{...router.resolve(link.path).query,from:route.fullPath}}">{{link.label}} →</RouterLink></div></section><section class="panel stack"><nav class="row profile-tabs" aria-label="用户资料分类"><button class="button" :class="{primary:tab==='products'}" :aria-pressed="tab==='products'" @click="change({tab:'products'})">发布商品</button><button class="button" :class="{primary:tab==='reviews'}" :aria-pressed="tab==='reviews'" @click="change({tab:'reviews'})">交易评价</button></nav><template v-if="tab==='products'"><label class="field-label">商品状态<select :value="productStatus" @change="change({status:($event.target as HTMLSelectElement).value,productPage:'1'})"><option value="ALL">在售与已售</option><option value="AVAILABLE">在售</option><option value="SOLD">已售出</option></select></label><PageState :loading="products.loading.value" :error="products.error.value" @retry="products.reload"><template v-if="products.data.value"><p v-if="!products.data.value.items.length" class="muted">暂无可展示的商品。</p><div class="profile-product-grid"><article v-for="product in products.data.value.items" :key="product.id" class="stack"><ProductPhoto :image="product.images[0]" :title="product.title" :category="product.category"/><RouterLink class="record-title" :to="{path:'/products/'+product.id,query:{from:route.fullPath}}">{{product.title}}</RouterLink><div class="row spread"><strong>{{money(product.price)}}</strong><StatusBadge :value="product.saleStatus"/></div></article></div><WorkPagination :page="products.data.value.page" :pages="Math.max(1,Math.ceil(products.data.value.total/20))" :total="products.data.value.total" @change="change({productPage:String($event)})"/></template></PageState></template><template v-else><label class="field-label">评价身份<select :value="reviewRole" @change="change({role:($event.target as HTMLSelectElement).value,reviewPage:'1'})"><option value="ALL">全部评价</option><option value="BUYER">作为买家收到的评价</option><option value="SELLER">作为卖家收到的评价</option></select></label><PageState :loading="reviews.loading.value" :error="reviews.error.value" @retry="reviews.reload"><template v-if="reviews.data.value"><PublicReviews :items="reviews.data.value.items"/><WorkPagination :page="reviews.data.value.page" :pages="Math.max(1,Math.ceil(reviews.data.value.total/20))" :total="reviews.data.value.total" @change="change({reviewPage:String($event)})"/></template></PageState></template></section></div></PageState></template>
